-- ==============================================================================
-- Graveyard pins (2026-09-17): where a player can entrust the Soul Ashes of the run.
--
-- The living talk to a Spirit Healer (visible to everyone now) to bank the run's Soul Ashes
-- and Soul Shards into the account, 5 times a week (+2 with the Ashen Offering nodes). This
-- module shows every graveyard of the current zone:
-- module shows the player graveyards of the current zone on the world map (WorldMapDetailFrame):
-- only real graveyards of the zone that have a Spirit Healer, same map-id keying as
-- modules/checkpoint (GetCurrentMapAreaID() = WorldMapArea id + 1).
-- Nothing on the minimap. Data: modules/graveyards/GraveyardData.lua, generated by
-- tools/graveyards/export_graveyards.py (world coordinates + the world rectangle of each
-- zone map). Faction-only graveyards (Alliance 469 / Horde 67) are hidden from the other faction.
-- ==============================================================================
ProjectEbonhold = ProjectEbonhold or {}
local GP = {}
ProjectEbonhold.GraveyardPins = GP

-- The corpse skull Blizzard draws on the world map (Interface\WorldMap\Skull_64Grey).
local ICON = "Interface\\WorldMap\\Skull_64Grey"
local ICON_COORDS = { 0, 1, 0, 1 }
local WORLD_PIN_SIZE = 24
local FACTION_ALLIANCE, FACTION_HORDE = 469, 67

local tooltip = CreateFrame("GameTooltip", "ProjectEbonholdGraveyardTooltip", nil, "GameTooltipTemplate")
tooltip:SetFrameStrata("TOOLTIP")
tooltip:SetClampedToScreen(true)

local function PlayerFactionId()
    local faction = UnitFactionGroup("player")
    if faction == "Alliance" then return FACTION_ALLIANCE end
    if faction == "Horde" then return FACTION_HORDE end
    return 0
end

local function IsForPlayer(graveyard)
    return graveyard.faction == 0 or graveyard.faction == PlayerFactionId()
end

local function OfferingsText()
    local data = ProjectEbonhold.PlayerRunService and ProjectEbonhold.PlayerRunService.GetCurrentData
        and ProjectEbonhold.PlayerRunService.GetCurrentData() or {}
    local max = data.banksMaxWeek or 0
    if max == 0 then return nil end
    local left = math.max(0, max - (data.banksUsedWeek or 0))
    return left .. "/" .. max .. " offerings left this week"
end

local function ShowTooltip(pin)
    tooltip:SetOwner(pin, "ANCHOR_CURSOR_RIGHT")
    tooltip:ClearLines()
    tooltip:AddLine(pin.graveyardName or "Graveyard", 1, 0.82, 0)
    tooltip:AddLine("Spirit Healer: entrust the Soul Ashes and Soul Shards of your run to your account here.", 1, 1, 1, true)
    local offerings = OfferingsText()
    if offerings then
        tooltip:AddLine(offerings, 0.6, 0.8, 1)
    end
    if pin.distance then
        tooltip:AddLine(string.format("%d yards away", pin.distance), 0.7, 0.7, 0.7)
    end
    tooltip:Show()
end

local function MakePin(parent, size)
    local pin = CreateFrame("Button", nil, parent)
    pin:SetSize(size, size)
    pin:EnableMouse(true)
    pin:SetHitRectInsets(-4, -4, -4, -4)
    pin.icon = pin:CreateTexture(nil, "ARTWORK")
    pin.icon:SetAllPoints(pin)
    pin.icon:SetTexture(ICON)
    pin.icon:SetTexCoord(unpack(ICON_COORDS))
    pin.highlight = pin:CreateTexture(nil, "HIGHLIGHT")
    pin.highlight:SetAllPoints(pin)
    pin.highlight:SetTexture(ICON)
    pin.highlight:SetTexCoord(unpack(ICON_COORDS))
    pin.highlight:SetBlendMode("ADD")
    pin.highlight:SetAlpha(0.4)
    pin:SetScript("OnEnter", ShowTooltip)
    pin:SetScript("OnLeave", function() tooltip:Hide() end)
    return pin
end

-- World coordinates -> fraction of the zone map (x north, y west; rect left > right, top > bottom).
local function ToMapFraction(rect, worldX, worldY)
    local fx = (rect.left - worldY) / (rect.left - rect.right)
    local fy = (rect.top - worldX) / (rect.top - rect.bottom)
    return fx, fy
end

-- ------------------------------------------------------------------ world map
local worldPins = {}

local function HideWorldPins(from)
    for i = from, #worldPins do worldPins[i]:Hide() end
end

function GP.RefreshWorldMap()
    -- IsVisible: the detail frame stays "shown" with the map closed (see checkpoint.lua)
    if not WorldMapDetailFrame or not WorldMapDetailFrame:IsVisible() then
        HideWorldPins(1)
        return
    end
    local data = ProjectEbonhold.GraveyardData
    local mapId = GetCurrentMapAreaID and GetCurrentMapAreaID() or 0
    local zone = data and data[mapId]
    if not zone then
        HideWorldPins(1)
        return
    end

    local frame = WorldMapDetailFrame
    local parent = WorldMapButton or frame
    local width, height = frame:GetWidth(), frame:GetHeight()
    local count = 0
    for _, gy in ipairs(zone.graveyards) do
        if IsForPlayer(gy) then
            local fx, fy = ToMapFraction(zone, gy.x, gy.y)
            if fx >= 0 and fx <= 1 and fy >= 0 and fy <= 1 then
                count = count + 1
                local pin = worldPins[count]
                if not pin then
                    pin = MakePin(parent, WORLD_PIN_SIZE)
                    pin:SetFrameStrata("FULLSCREEN_DIALOG")
                    pin:SetToplevel(true)
                    worldPins[count] = pin
                end
                pin:SetParent(parent)
                pin:SetFrameLevel(frame:GetFrameLevel() + 15)
                pin:ClearAllPoints()
                pin:SetPoint("CENTER", frame, "TOPLEFT", fx * width, -fy * height)
                pin.graveyardName = gy.name
                pin.distance = nil
                pin:Show()
            end
        end
    end
    HideWorldPins(count + 1)
end

-- ------------------------------------------------------------------ events
local eventFrame = CreateFrame("Frame")
eventFrame:RegisterEvent("WORLD_MAP_UPDATE")
eventFrame:SetScript("OnEvent", function() GP.RefreshWorldMap() end)

if WorldMapDetailFrame then
    WorldMapDetailFrame:HookScript("OnShow", GP.RefreshWorldMap)
    WorldMapDetailFrame:HookScript("OnHide", function()
        tooltip:Hide()
        HideWorldPins(1)
    end)
end
